package com.adib.maintenance;
public final class WorkTimeEditTest {
 public static void main(String[] args){long original=1760523000123L;String value=WorkTimeEdit.format(original);if(WorkTimeEdit.editedMillis(value,original)!=original)throw new AssertionError("unchanged precision");long edited=WorkTimeEdit.editedMillis("15.10.2026 10:15:30",original);if(!"15.10.2026 10:15:30".equals(WorkTimeEdit.format(edited)))throw new AssertionError("round trip");for(String bad:new String[]{"31.02.2026 10:00:00","15.10.2026 25:00:00","15.10.2026 10:00:00 trailing","15.10.2026 10:00"}){try{WorkTimeEdit.editedMillis(bad,original);throw new AssertionError("accepted "+bad);}catch(IllegalArgumentException expected){}}try{WorkTimeEdit.validate(original,original);throw new AssertionError("equal times");}catch(IllegalArgumentException expected){}try{WorkTimeEdit.validate(original,original-1000);throw new AssertionError("reversed times");}catch(IllegalArgumentException expected){}WorkTimeEdit.validate(original,original+1000);System.out.println("PASS: date/time editing, precision, invalid dates, ordering");}
}
